svg.metadata:
# netdiagram — describe the network, get a schematic. # diagram: options title + direction control rendering; # any other scalar key is an attribute shown in the title block # nodes: id, label, type/icon, ip|ips, os, tags: [..] # platform types vm|metal|container (+ aliases like docker, baremetal, # server, "physical server", dedicated) draw the platform glyph AND set # the border style (dashed/double/dotted) # tags are informational: neutral pills top-right, two per row # any other scalar key is rendered as "key: value" on the node # groups: class: zone|vlan|subnet|cloud|onprem|trust, cidr # cidr + any other scalar key render in an info box bottom-right in the group # connections: from/to can be node OR group ids # label (optional) shown on edge; connections sharing the same label share a color # protocol: tcp|udp|icmp|vrrp|any port: number or range # direction: forward (default) | both | none diagram: title: HQ edge & core direction: down author: remy revision: "1.2"
nodes: - id: inet label: Internet type: internet - id: fw1 label: Edge FW A type: firewall ip: 203.0.113.1 os: bsd tags: [ha] - id: fw2 label: Edge FW B type: firewall ip: 203.0.113.2 os: bsd tags: [ha] - id: waf label: WAF type: waf - id: web1 label: web-01 type: server ip: 10.0.10.11 os: linux - id: core label: Core Switch type: switch - id: app1 label: app-01 type: vm # platform type: VM glyph + dashed border ip: 10.0.20.11 os: linux - id: api1 label: api-01 type: container # platform type: container glyph + dotted border ip: 10.0.20.12 os: linux tags: [prod, pci] # informational pills, two per row - id: db1 label: pg-primary type: metal # bare-metal database; icon keeps the db glyph icon: db ips: [10.0.20.21, 10.0.99.21] os: linux - id: mgmt label: Mgmt Station type: user ip: 10.0.99.5 os: windows - id: siem label: SIEM type: siem
groups: - id: onprem label: On-prem — HQ class: onprem nodes: [fw1, fw2] groups: - id: dmz label: DMZ (VLAN 10) class: zone cidr: 10.0.10.0/24 nodes: [waf, web1] - id: lan label: Server LAN (VLAN 20) class: trust tags: [pci] # group tags: pills tinted in the group's own color cidr: 10.0.20.0/24 owner: netops nodes: [core, app1, api1, db1] - id: oob label: Mgmt (VLAN 99) class: vlan cidr: 10.0.99.0/24 nodes: [mgmt] - id: cloud label: Cloud — logging class: cloud nodes: [siem]
connections: # edge labels follow "<proto>/<port> <context>"; any/vrrp/deny flows keep a plain note - {from: inet, to: fw1, label: "tcp/443 https", protocol: tcp, port: 443, comment: "public HTTPS ingress"} - {from: inet, to: fw2, label: "tcp/443 https", protocol: tcp, port: 443} - {from: fw1, to: fw2, label: "vrrp ha", protocol: vrrp, direction: both, comment: "firewall HA heartbeat"} - {from: fw1, to: waf, label: "tcp/443 https", protocol: tcp, port: 443} - {from: waf, to: web1, label: "tcp/8443 https", protocol: tcp, port: 8443} - {from: fw1, to: core, protocol: any} - {from: fw2, to: core, protocol: any} - {from: core, to: app1, label: "tcp/8080 app", protocol: tcp, port: 8080} - {from: core, to: api1, label: "tcp/8080 api", protocol: tcp, port: 8080} - {from: web1, to: app1, label: "tcp/8443 app", protocol: tcp, port: 8443} - {from: app1, to: db1, label: "tcp/5432 pgsql", protocol: tcp, port: 5432, direction: both, comment: "app read/write + replication"} - {from: api1, to: db1, label: "tcp/5432 pgsql", protocol: tcp, port: 5432} - {from: oob, to: lan, label: "tcp/22 ssh", protocol: tcp, port: 22} - {from: oob, to: fw1, label: "tcp/22 ssh", protocol: tcp, port: 22, comment: "mgmt from the jump host"} - {from: dmz, to: siem, label: "udp/514 syslog", protocol: udp, port: 514} - {from: lan, to: siem, label: "udp/514 syslog", protocol: udp, port: 514} - {from: web1, to: db1, label: "blocked", direction: none, comment: "web tier must not reach the DB directly"}
# views: one document, several pictures of it. Pick one with # `npm run render -- file.yaml --view edge`, or from the View picker in the app. views: - {id: edge, title: "HQ — edge", focus: fw1, depth: 1} - {id: pci, title: "HQ — PCI scope", tags: [pci]} - {id: mgmt, title: "HQ — management access", focus: oob, depth: 1, direction: right}
